    // Commit Object & Sync
    function commitObject(obj) {
      boardObjects[obj.id] = obj;
      undoStack.push(obj.id);
      render();

      if (isFirebaseReady && dbRef) {
        dbRef.child('objects/' + obj.id).set(obj);
      } else {
        localStorage.setItem('cb_' + currentRoomId, JSON.stringify(boardObjects));
      }
    }

